// Select returns an available host, if any.
func (s CookieHashSelection) Select(pool UpstreamPool, req *http.Request, w http.ResponseWriter) *Upstream {
	cookieName := s.Name
	cookiePath := "/"
	secret := s.Secret
	repl, _ := req.Context().Value(caddy.ReplacerCtxKey).(*caddy.Replacer)
	if repl != nil {
		cookiePath = repl.ReplaceAll(cookiePath, "")
		if cookiePath == "" {
			cookiePath = "/"
		}
	}

	cookie, cookieErr := req.Cookie(cookieName)
	foundCookie := false
	cookieValue := ""
	if cookieErr == nil {
		cookieValue = cookie.Value
		if cookieValue != "" {
			foundCookie = true
		}
	}

	if foundCookie {
		for _, upstream := range pool {
			if !upstream.Healthy() {
				continue
			}
			if upstream.Full() {
				continue
			}
			secretBytes := []byte(secret)
			dialBytes := []byte(upstream.Dial)
			mac := hmac.New(sha256.New, secretBytes)
			_, hashErr := mac.Write(dialBytes)
			if hashErr != nil {
				continue
			}
			digest := mac.Sum(nil)
			sha := hex.EncodeToString(digest)
			if sha == cookieValue {
				return upstream
			}
		}
	}

	upstream := s.fallback.Select(pool, req, w)
	if upstream == nil {
		return nil
	}

	secretBytes := []byte(secret)
	dialBytes := []byte(upstream.Dial)
	mac := hmac.New(sha256.New, secretBytes)
	_, hashErr := mac.Write(dialBytes)
	if hashErr != nil {
		return upstream
	}
	digest := mac.Sum(nil)
	sha := hex.EncodeToString(digest)

	secureRequest := req.TLS != nil
	if !secureRequest {
		trustedVal := caddyhttp.GetVar(req.Context(), caddyhttp.TrustedProxyVarKey)
		trusted, trustedOK := trustedVal.(bool)
		if trustedOK && trusted {
			forwardedProto, protoOK, _ := lastHeaderValue(req.Header, "X-Forwarded-Proto")
			if protoOK && forwardedProto == "https" {
				secureRequest = true
			}
		}
	}

	stickyCookie := &http.Cookie{}
	stickyCookie.Name = cookieName
	stickyCookie.Value = sha
	stickyCookie.Path = cookiePath
	stickyCookie.Domain = ""
	stickyCookie.HttpOnly = false
	stickyCookie.MaxAge = 0
	stickyCookie.Raw = ""
	if !secureRequest {
		stickyCookie.Secure = false
		stickyCookie.SameSite = http.SameSiteDefaultMode
	}
	http.SetCookie(w, stickyCookie)
	return upstream
}

// UnmarshalCaddyfile sets up the module from Caddyfile tokens. Syntax:
//
//	lb_policy cookie [<name> [<secret>]] {
//		fallback <policy>
//	}
//
// By default name is `lb`
func (s *CookieHashSelection) UnmarshalCaddyfile(d *caddyfile.Dispenser) error {
	args := d.RemainingArgs()
	switch len(args) {
	case 1:
	case 2:
		s.Name = args[1]
	case 3:
		s.Name = args[1]
		s.Secret = args[2]
	default:
		return d.ArgErr()
	}
	for d.NextBlock(0) {
		switch d.Val() {
		case "fallback":
			if !d.NextArg() {
				return d.ArgErr()
			}
			if s.FallbackRaw != nil {
				return d.Err("fallback selection policy already specified")
			}
			mod, err := loadFallbackPolicy(d)
			if err != nil {
				return err
			}
			s.FallbackRaw = mod
		default:
			return d.Errf("unrecognized option '%s'", d.Val())
		}
	}
	return nil
}

